<script setup lang="ts">import{ref}from'vue';import AppShell from'../components/AppShell.vue';import{api}from'../services/api';const content=ref(''),mode=ref('OFFICE'),msg=ref('');async function save(){try{await api('/api/daily-work/today',{method:'PUT',body:JSON.stringify({work_content:content.value,work_mode:mode.value})});msg.value='Đã cập nhật công việc hôm nay'}catch(e:any){msg.value=e.message}}</script><template><AppShell><main class="page"><div class="title">Công việc hôm nay</div><p class="muted">Cho quản lý biết bạn đang tập trung vào việc gì.</p><div class="card form"><v-textarea v-model="content" label="Hôm nay tôi làm gì?" rows="5" counter="500"/><v-select v-model="mode" label="Hình thức làm việc" :items="[{title:'Tại văn phòng',value:'OFFICE'},{title:'Làm việc từ xa',value:'REMOTE'}]"/><v-alert v-if="msg" type="success" density="compact">{{msg}}</v-alert><v-btn color="#8b0d24" size="large" @click="save">Lưu cập nhật</v-btn></div></main></AppShell></template><style scoped>.form{max-width:720px;margin-top:20px}</style>
